window.RI2_UNITS = {"3":{"unit":3,"code":"RI2-U03","title":"HISTORY DETECTIVES","startNumber":65,"endNumber":92,"entries":[{"number":65,"term":"tomb ~ grave","sourceTerm":"tomb ~ grave","spoken":"tomb , grave","ipa":"tomb /tuːm/ · grave /ɡreɪv/","type":"noun · noun","meaning":"lăng mộ, mộ có công trình ~ phần mộ đào trong đất","definition":"A tomb is a structure or chamber for a dead person; a grave is a place dug in the ground for burial.","note":"Tomb là công trình hoặc nơi chôn người chết. Grave thường là phần mộ được đào trong đất.","example":"Archaeologists entered the stone tomb and found a grave beneath its floor."},{"number":66,"term":"archaeology · archaeologist","sourceTerm":"archaeology · archaeologist","spoken":"archaeology , archaeologist","ipa":"archaeology /ˌɑːrkiˈɑːlədʒi/ · archaeologist /ˌɑːrkiˈɑːlədʒɪst/","type":"noun · noun","meaning":"khảo cổ học · nhà khảo cổ học","definition":"Archaeology studies past societies through physical remains; an archaeologist conducts this study.","note":"Archaeology là ngành học. Archaeologist là người nghiên cứu. Học các từ cùng gốc và chọn đúng dạng theo vị trí trong câu.","example":"The archaeologist used modern technology to answer a question that had challenged archaeology for decades."},{"number":67,"term":"rule","sourceTerm":"rule (v)","spoken":"rule","ipa":"rule /ruːl/","type":"verb","meaning":"thống trị, cai trị","definition":"To control and govern a country, territory, or people.","note":"Rule + quốc gia/vùng lãnh thổ. Rule over + người hoặc vùng cũng được dùng.","example":"The queen ruled the kingdom during a period of political change."},{"number":68,"term":"lie – lay – lain # lie – lied – lied # lay – laid – laid","sourceTerm":"lie – lay – lain # lie – lied – lied # lay – laid – laid","spoken":"lie – lay – lain , lie – lied – lied , lay – laid – laid","ipa":"lie /laɪ/ · lay /leɪ/ · lain /leɪn/ · lied /laɪd/ · laid /leɪd/","type":"verb · verb · verb","meaning":"nằm · nói dối · đặt, để","definition":"Lie–lay–lain means to be in a position; lie–lied–lied means to say something untrue; lay–laid–laid means to put something down.","note":"Lie mang nghĩa nằm và không cần tân ngữ. Lay mang nghĩa đặt và cần tân ngữ. Ba bộ dạng quá khứ phải học riêng.","example":"The crown had lain beside the body for centuries, although an early witness lied about who had laid it there."},{"number":69,"term":"clue","sourceTerm":"clue (n)","spoken":"clue","ipa":"clue /kluː/","type":"noun","meaning":"manh mối, gợi ý","definition":"A fact, object, or piece of information that helps solve a question or mystery.","note":"A clue to/about sth chỉ manh mối về điều gì.","example":"A small fracture in the skull provided an important clue about the person's death."},{"number":70,"term":"attempt to do sth ~ effort","sourceTerm":"attempt to do sth ~ effort","spoken":"attempt to do something , effort","ipa":"attempt /əˈtɛmpt/ · effort /ˈɛfɚt/","type":"verb · noun · noun · phrase / pattern","meaning":"cố gắng làm một việc cụ thể ~ công sức, nỗ lực bỏ ra","definition":"An attempt is a specific act of trying; effort is the physical or mental energy used to achieve something.","note":"Attempt to do sth. Make an attempt to do sth. Make an effort to do sth. Effort thường không đếm được khi nói về công sức nói chung.","example":"The first attempt to identify the remains failed despite the team's considerable effort."},{"number":71,"term":"attach # attack","sourceTerm":"attach # attack","spoken":"attach , attack","ipa":"attach /əˈtætʃ/ · attack /əˈtæk/","type":"verb · verb · noun","meaning":"gắn, đính kèm · tấn công; cuộc tấn công","definition":"Attach means to fasten or connect; attack means to act violently against a person, place, or system.","note":"Attach A to B mang nghĩa gắn A vào B. Attack + tân ngữ mang nghĩa tấn công. Hai từ gần giống chữ nhưng khác nghĩa.","example":"The invaders attacked the tomb and attached ropes to its heavy door."},{"number":72,"term":"a great/good deal of sth ~ a lot of sth ~ a large number of sth","sourceTerm":"a great/good deal of sth ~ a lot of sth ~ a large number of sth","spoken":"a great or good deal of something , a lot of something , a large number of something","ipa":"great /ɡreɪt/ · good /ɡʊd/ · deal /diːl/ · lot /lɑːt/ · large /lɑːrdʒ/ · number /ˈnʌmbɚ/","type":"noun · noun · noun · phrase / pattern","meaning":"rất nhiều, một lượng hoặc số lượng lớn","definition":"A great or good deal of expresses a large amount with an uncountable noun; a large number of is used with plural countable nouns.","note":"A great/good deal of + danh từ không đếm được. Với danh từ đếm được số nhiều, dùng a large number of.","example":"The investigation required a great deal of patience and a lot of careful analysis, as well as a large number of samples."},{"number":73,"term":"conduct ~ carry out ~ perform","sourceTerm":"conduct (v) ~ carry out (phr v) ~ perform (v)","spoken":"conduct , carry out , perform","ipa":"conduct /kənˈdʌkt/ · carry /ˈkæri/ · out /aʊt/ · perform /pɚˈfɔːrm/","type":"verb · phrasal verb · verb","meaning":"thực hiện, tiến hành (cuộc nghiên cứu, điều tra, khảo sát…)","definition":"To organize and complete a study, test, investigation, or other planned activity.","note":"Conduct/carry out research, an experiment, a survey. Perform a test/procedure. Chọn kết hợp tự nhiên theo danh từ đi kèm.","example":"The team conducted a DNA test, carried out further research, and performed the final procedure under controlled conditions."},{"number":74,"term":"analyze · analysis","sourceTerm":"analyze · analysis","spoken":"analyze , analysis","ipa":"analyze /ˈænəˌlaɪz/ · analysis /əˈnæləsəs/","type":"verb · noun","meaning":"phân tích · sự phân tích","definition":"To examine something carefully by studying its parts or evidence; analysis is this examination.","note":"Analyze là động từ. Analysis là danh từ. Học đúng sự thay đổi chính tả khi chuyển dạng.","example":"Scientists analyzed the bones, and their analysis revealed signs of disease."},{"number":75,"term":"vulnerable to sth","sourceTerm":"vulnerable (a) to sth","spoken":"vulnerable to something","ipa":"vulnerable /ˈvʌlnɚəbəl/","type":"adjective · phrase / pattern","meaning":"dễ bị tổn thương bởi…","definition":"Easily harmed, damaged, or affected by a particular danger.","note":"Be vulnerable to + danh từ/V-ing.","example":"Old remains are vulnerable to damage when they are exposed to air."},{"number":76,"term":"fracture","sourceTerm":"fracture (n)","spoken":"fracture","ipa":"fracture /ˈfræktʃɚ/","type":"noun","meaning":"vết nứt, chỗ gãy","definition":"A crack or break in a bone or another hard material.","note":"Fracture có thể là danh từ hoặc động từ. Dòng này dùng nghĩa danh từ.","example":"The scan showed a narrow fracture near the back of the skull."},{"number":77,"term":"bury · burial","sourceTerm":"bury · burial","spoken":"bury , burial","ipa":"bury /ˈbɛri/ · burial /ˈbɛriəl/","type":"verb · noun","meaning":"chôn cất · việc hoặc nghi lễ chôn cất","definition":"To place a dead body in the ground; burial is the act or ceremony of doing this.","note":"Bury – buried – buried. Burial có cách viết thay đổi ở phần gốc, cần học đúng dạng.","example":"The community buried its leaders with valuable objects, and each burial followed a formal ritual."},{"number":78,"term":"rule out","sourceTerm":"rule out (phr.V)","spoken":"rule out","ipa":"rule /ruːl/ · out /aʊt/","type":"phrasal verb","meaning":"loại bỏ (một khả năng)","definition":"To decide that something is impossible or not responsible after considering the evidence.","note":"Rule out + khả năng/nguyên nhân. Cấu trúc này thường dùng khi bằng chứng cho phép loại bỏ giả thuyết.","example":"The medical evidence ruled out disease as the cause of death."},{"number":79,"term":"reject","sourceTerm":"reject (v)","spoken":"reject","ipa":"reject /rɪˈdʒɛkt/","type":"verb","meaning":"từ chối, bác bỏ","definition":"To refuse to accept, believe, or approve something.","note":"Reject + danh từ. Không dùng reject to do. Từ này thường diễn tả sự từ chối hoặc bác bỏ dứt khoát.","example":"The researchers rejected the early theory because it did not fit the evidence."},{"number":80,"term":"properly","sourceTerm":"properly (adv)","spoken":"properly","ipa":"properly /ˈprɑːpɚli/","type":"adverb","meaning":"đúng cách; bình thường","definition":"In the correct, suitable, or expected way.","note":"Properly có thể là đúng cách, đầy đủ hoặc hoạt động bình thường tùy văn cảnh.","example":"Each object was properly labeled before it left the site."},{"number":81,"term":"beyond","sourceTerm":"beyond (pre)","spoken":"beyond","ipa":"beyond /bɪˈɑːnd/","type":"preposition","meaning":"vượt ngoài…","definition":"Farther than a place, limit, period, or level that has been mentioned.","note":"Beyond + danh từ. Beyond còn dùng cho điều vượt quá khả năng hoặc giới hạn.","example":"The search extended beyond the tomb to several nearby buildings."},{"number":82,"term":"indicate","sourceTerm":"indicate (v)","spoken":"indicate","ipa":"indicate /ˈɪndəˌkeɪt/","type":"verb","meaning":"chỉ ra; ngụ ý, ám chỉ rằng…","definition":"To show, suggest, or point to a particular fact or conclusion.","note":"Indicate that + mệnh đề. Indicate sth to sb. Từ này cho thấy bằng chứng hướng tới kết luận, chưa nhất thiết chứng minh tuyệt đối.","example":"Damage to the bones indicated that the person had suffered an injury."},{"number":83,"term":"expose sb to sth · be exposed to sth · exposure","sourceTerm":"expose sb to sth · be exposed to sth · exposure","spoken":"expose somebody to something , be exposed to something , exposure","ipa":"expose /ɪˈkspoʊz/ · exposed /ɪˈkspoʊzd/ · exposure /ɪˈkspoʊʒɚ/","type":"verb · verb · noun · phrase / pattern","meaning":"để ai hoặc vật tiếp xúc với · tiếp xúc, chịu tác động của · sự tiếp xúc; mức độ phơi nhiễm","definition":"To place someone or something in contact with a harmful condition; exposure is the state or period of contact.","note":"Expose A to B ở thể chủ động. A be exposed to B ở thể bị động. Exposure to + danh từ.","example":"Opening the tomb exposed the remains to moisture, and prolonged exposure damaged the surface."},{"number":84,"term":"flee – fled – fled","sourceTerm":"flee (v) – fled – fled","spoken":"flee – fled – fled","ipa":"flee /fliː/ · fled /flɛd/","type":"verb","meaning":"chạy trốn, lẩn trốn","definition":"To escape quickly from a dangerous person, place, or situation.","note":"Flee + nơi/người hoặc flee from + nơi/người. Không cần dùng away sau flee.","example":"Historical records suggest that residents fled the city during the invasion."},{"number":85,"term":"religion · religious # region","sourceTerm":"religion · religious # region","spoken":"religion , religious , region","ipa":"religion /rɪˈlɪdʒən/ · religious /rɪˈlɪdʒəs/ · region /ˈriːdʒən/","type":"noun · noun · adjective","meaning":"tôn giáo · thuộc tôn giáo; có tính tôn giáo · khu vực, vùng miền","definition":"Religion is a system of beliefs and practices; religious describes those beliefs, while a region is a geographical area.","note":"Religion là danh từ. Religious là tính từ. Không nhầm religion với region.","example":"The objects may have had a religious purpose within the ancient religion practiced in that region."},{"number":86,"term":"prove >< disprove · proof ~ evidence","sourceTerm":"prove >< disprove · proof ~ evidence","spoken":"prove , disprove , proof , evidence","ipa":"prove /pruːv/ · disprove /dɪˈspruːv/ · proof /pruːf/ · evidence /ˈɛvədəns/","type":"verb · verb · noun · noun","meaning":"chứng minh là đúng · chứng minh là sai, bác bỏ · bằng chứng xác thực; sự chứng minh ~ bằng chứng, dữ liệu hỗ trợ","definition":"To prove is to show that something is true; to disprove is to show it is false; proof is conclusive, while evidence supports a conclusion.","note":"Evidence thường là dữ liệu hoặc dấu hiệu hỗ trợ. Proof là bằng chứng đủ sức xác nhận chắc chắn. Evidence là danh từ không đếm được.","example":"The new evidence did not prove the theory, but it helped disprove an earlier claim; final proof required another test."},{"number":87,"term":"investigate · investigation","sourceTerm":"investigate · investigation","spoken":"investigate , investigation","ipa":"investigate /ˌɪˈnvɛstəˌɡeɪt/ · investigation /ˌɪˌnvɛstəˈɡeɪʃən/","type":"verb · noun","meaning":"điều tra, nghiên cứu có hệ thống · cuộc hoặc quá trình điều tra","definition":"To examine facts and evidence systematically in order to discover the truth; an investigation is this process.","note":"Investigate + vấn đề/vụ việc, không dùng investigate about.","example":"Experts investigated the unexplained death, and the investigation lasted three years."},{"number":88,"term":"distinguish A from B · distinguish between A and B","sourceTerm":"distinguish A from B · distinguish between A and B","spoken":"distinguish A from B , distinguish between A and B","ipa":"distinguish /dɪˈstɪŋɡwɪʃ/ · between /bɪˈtwiːn/","type":"verb · verb","meaning":"phân biệt A với B · phân biệt giữa A và B","definition":"To recognize or explain the difference between two people, things, or ideas.","note":"Dùng đúng hai cấu trúc. Distinguish A from B. Distinguish between A and B.","example":"DNA testing enabled scientists to distinguish the ruler's remains from those of other family members."},{"number":89,"term":"speculate · speculation","sourceTerm":"speculate · speculation","spoken":"speculate , speculation","ipa":"speculate /ˈspɛkjəˌleɪt/ · speculation /ˌspɛkjəˈleɪʃən/","type":"verb · noun","meaning":"phỏng đoán khi chưa đủ bằng chứng · sự phỏng đoán","definition":"To form a possible explanation without enough evidence for certainty; speculation is such an idea or discussion.","note":"Speculate about/on sth. Speculate that + mệnh đề. Từ này báo hiệu kết luận chưa chắc chắn.","example":"Historians speculated about the ruler's death, but their speculation could not replace physical evidence."},{"number":90,"term":"enable sb to do sth ~ allow sb to do sth","sourceTerm":"enable (v) sb to do sth ~ allow (v) sb to do sth","spoken":"enable somebody to do something , allow somebody to do something","ipa":"enable /ɛˈneɪbəl/ · allow /əˈlaʊ/","type":"verb · verb · phrase / pattern","meaning":"cho phép, tạo điều kiện cho ai làm gì","definition":"To give someone the ability, means, or opportunity to do something.","note":"Enable nhấn mạnh tạo khả năng hoặc điều kiện. Allow thường nhấn mạnh cho phép. Cả hai dùng sb to do sth.","example":"Digital scans enabled researchers to examine the body without moving it and allowed the museum to preserve the remains."},{"number":91,"term":"ceremony ~ ritual","sourceTerm":"ceremony ~ ritual","spoken":"ceremony , ritual","ipa":"ceremony /ˈsɛrəˌmoʊni/ · ritual /ˈrɪtʃuəl/","type":"noun · noun","meaning":"buổi lễ, nghi lễ trang trọng ~ nghi thức, chuỗi hành động mang tính nghi lễ","definition":"A ceremony is a formal event; a ritual is a fixed series of symbolic actions that may form part of it.","note":"Ceremony là sự kiện trang trọng cụ thể. Ritual là chuỗi hành động theo nghi thức.","example":"The burial ceremony included a ritual in which relatives placed symbolic objects beside the body."},{"number":92,"term":"likely · likelihood >< unlikely","sourceTerm":"likely · likelihood >< unlikely","spoken":"likely , likelihood , unlikely","ipa":"likely /ˈlaɪkli/ · likelihood /ˈlaɪkliˌhʊd/ · unlikely /əˈnlaɪkli/","type":"noun · adjective · adjective · adverb · adverb","meaning":"có khả năng xảy ra · khả năng xảy ra · khó có khả năng xảy ra","definition":"Likely means expected to happen; unlikely means not expected, and likelihood is the chance that it will happen.","note":"Be likely/unlikely to do sth. Likelihood of + danh từ/V-ing. Likelihood that + mệnh đề.","example":"The injury was likely to have occurred before death; the likelihood of an accident seemed low, and disease was an unlikely cause."}],"pronunciationFocus":[{"entryNumber":65,"points":[{"category":"silent-letter","note":"Chữ b trong tomb không được phát âm"},{"category":"final-sound","note":"tomb kết thúc trực tiếp bằng /m/"}]},{"entryNumber":66,"points":[{"category":"word-stress","note":"archaeology và archaeologist đều nhấn vào âm tiết chứa /ɑːl/"}]},{"entryNumber":70,"points":[{"category":"word-stress","note":"attempt nhấn âm tiết thứ hai; effort nhấn âm đầu"},{"category":"final-sound","note":"attempt kết thúc bằng cụm /mpt/; không bỏ /p/ hoặc /t/"}]},{"entryNumber":73,"points":[{"category":"word-stress","note":"conduct trong nghĩa thực hiện là động từ /kənˈdʌkt/ và nhấn âm tiết thứ hai"},{"category":"final-sound","note":"conduct kết thúc bằng cụm /kt/"}]},{"entryNumber":78,"points":[{"category":"linking","note":"Đọc liền rule‿out, nối /l/ cuối rule sang nguyên âm /aʊ/ của out"}]},{"entryNumber":85,"points":[{"category":"common-error","note":"religion nhấn âm tiết thứ hai; region nhấn âm đầu và có nguyên âm dài /iː/"}]},{"entryNumber":87,"points":[{"category":"word-stress","note":"investigate nhấn vào âm tiết chứa /vɛs/; investigation chuyển trọng âm sang âm tiết chứa /ɡeɪ/"}]}]}};
